import { i18n } from 'src/boot/i18n';
import { notify } from 'src/components/notifications/notify';

export const call_us = '081217929822';

export const SUPPORT_EMAIL = 'support@fellow-consulting.de';
export const SUPPORT_SUBJECT_RULES = 'Doc² Rules';

export function createSupportMailtoLink(subject: string, body: string): string {
  return `mailto:${SUPPORT_EMAIL}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
}

export function createRulesSupportMailtoLink(): string {
  const body = 'Document link: ' + window.location.href;
  return createSupportMailtoLink(SUPPORT_SUBJECT_RULES, body);
}

export function showRulesNotCreatedWarning(record: any): (() => void) | undefined {
  if (record?.doc_type === 'XML_INVOICE') {
    return undefined;
  }

  if (!record?.hasOwnProperty('filter_values') || !record?.filter_values) {
    const mailto = createRulesSupportMailtoLink();
    const message = i18n.t('rules_cannot_be_created', {
      link: `<a target="_blank" href="${mailto}">`,
      linkEnd: '</a>',
    });
    const id = notify.warning(message, {
      duration: Infinity,
    });
    return () => notify.dismiss(id);
  }

  return undefined;
}
